<template><div class="growth-page"><header><div><el-tag>AI能力提升建议</el-tag><h1>能力提升中心</h1><p>根据岗位胜任力评估报告生成的个人提升路线</p></div><el-button @click="router.push('/report')">返回评估报告</el-button></header><el-alert :title="`当前优先短板：${weakness.name}`" :description="`当前 ${weakness.score || 0} 分，岗位目标 ${weakness.targetScore || 0} 分，建议优先补齐工程实践。`" type="warning" :closable="false" show-icon/><el-row :gutter="18" class="plans"><el-col v-for="(item,index) in plans" :key="item.category" :span="8"><el-card shadow="never"><el-tag type="info">阶段 {{ index+1 }}</el-tag><h2>{{ item.category }}</h2><p>{{ item.action }}</p><el-divider/><strong>建议训练</strong><p>{{ item.resource }}</p></el-card></el-col></el-row><el-card shadow="never"><template #header><strong>推荐能力路线</strong></template><el-steps :active="0" align-center><el-step title="Spring Boot接口设计" description="参数校验、异常处理、鉴权与接口规范"/><el-step title="Docker部署" description="容器化、日志、健康检查和环境配置"/><el-step title="AI Agent工程实践" description="工具调用、状态管理、评测与可观测性"/></el-steps></el-card><div class="actions"><el-button @click="router.push('/assessment-history')">查看历史评估</el-button><el-button type="primary" @click="router.push('/resume-analysis')">重新开始岗位评估</el-button></div></div></template>
<script setup>import {computed} from "vue";import {useRouter} from "vue-router";import {useAssessmentStore} from "@/store/assessment";const router=useRouter();const store=useAssessmentStore();const weakness=computed(()=>[...(store.session.report?.competencyScores||store.session.competencyModel||[])].sort((a,b)=>(a.score-a.targetScore)-(b.score-b.targetScore))[0]||{name:"后端接口能力",score:72,targetScore:85});const plans=computed(()=>store.session.report?.growthPlan?.length?store.session.report.growthPlan:[{category:"Spring Boot接口设计",action:"完成参数校验、统一异常、鉴权和接口文档实践。",resource:"接口设计专项练习"},{category:"Docker部署",action:"将 AI 问答项目容器化并增加日志与健康检查。",resource:"容器化部署实践"},{category:"AI Agent工程实践",action:"实现工具调用、状态管理、评测和可观测性闭环。",resource:"Agent工程项目实践"}]);</script>
